    // ---------- статусы ----------
    const status = {};
    INN.forEach(p => (status[p.id] = [['alibi_' + p.id, 'алиби подтверждено', 'green']]));
    status[CU.id] = [['detained', 'задержан' + G(CU, '', 'а'), 'red'], ['confession', 'признал' + G(CU, 'ся', 'ась'), 'gold']];

    // ---------- сборка ----------
    const summon = {};
    S.forEach(p => (summon[p.id] = { req: ['k_' + p.id] }));
    if (FR) summon[FR.id] = { req: ['k_' + FR.id] };
    const pp = {};
    const colleague = window.CASES && window.CASES[0] ? window.CASES[0].people : null;
    ['gromov', 'vera', 'liza', 'partner', 'kin'].forEach(k => { if (colleague && colleague[k]) pp[k] = colleague[k]; });
    Object.values(people).forEach(p => { pp[p.id] = { name: p.name, role: p.role.charAt(0).toUpperCase() + p.role.slice(1), f: p.f, age: p.age, pt: p.pt, db: p.db, victim: p.victim }; });
